"""Offline barrier for scrapers/azure/run.py — unit types as rows, the «Paid annually» tab as the
period, the status badges, the ambiguous city, and the removal oracle.

Every HTML fragment below is VERBATIM azure.sa markup captured live on 2026-09-24, trimmed to the
blocks the code reads:
  · REEM_*   — /compounds/al-reem: both tab panels (6 unit types: Studio Apartment … 4 Bedroom
               Villa), <title>, og:description, the intro paragraph, the «Fully furnished» heading
               block and the <h1>;
  · WADI_*   — /compounds/wadi: the «Fully Leased» badge, both panels, <title>, og:description and
               one gallery <source>;
  · KAFD_*   — /compounds/kafd: both panels (bare «1 Bedroom» names, «2 Bedroom Duplex»);
  · QASSIM_* — /compounds/qassim: <title> naming «Al Qassim, Riyadh», the intro, the annual panel;
  · PALMA1_* — /compounds/palma-i: the «Coming Soon» badge;  PALMA2_* — «4 Bedroom Villas».
The functions under test are the production ones; only to_catalog / find_district_in_text are
stubbed.

WHAT IT PINS
  1. GRAIN: one row per unit type, ad_number = AZR<compound slug>-<unit key>; listing_url = the page.
  2. PRICE/PERIOD: the annual panel's «from 125 000 SAR» → price_annual 125000, rent_period annual,
     price_note "from", the monthly «… SAR/MONTH» kept as text only — never ×12 into the price.
  3. STATUS: Fully Leased / Coming Soon pages yield no rows and their own skip reason.
  4. CITY: exactly one city word or nothing — qassim (Al Qassim + Riyadh) is city_ambiguous.
  5. TYPE: bare «1 Bedroom» / «Triplex» are type_unmapped; Townhouse→Villa; «Villas» plural maps.
  6. FURNISHED from the block's own «Fully furnished»; «Optional: Terrace» is NOT an amenity.
  7. DISTRICT only when the title's own name is catalogued for that city (Qurtubah → حي قرطبة).
  8. ORACLE: 404 gone; badge gone; unit key absent gone; present live; 403 → law → unknown.
  9. main(): the tally reaches end_run(notes=...); prune only after a complete walk.
"""
from __future__ import annotations

import sys
import types

import pytest

_supabase_mod = types.ModuleType("supabase")


class _StubClient:  # pragma: no cover
    pass


_supabase_mod.Client = _StubClient
_supabase_mod.create_client = lambda url, key: _StubClient()
sys.modules.setdefault("supabase", _supabase_mod)
_dotenv_mod = types.ModuleType("dotenv")
_dotenv_mod.load_dotenv = lambda *a, **k: None
sys.modules.setdefault("dotenv", _dotenv_mod)

from scrapers.azure import run as A  # noqa: E402
from scrapers.common import http_liveness  # noqa: E402

REEM = "https://azure.sa/compounds/al-reem"
WADI = "https://azure.sa/compounds/wadi"
KAFD = "https://azure.sa/compounds/kafd"


@pytest.fixture(autouse=True)
def _catalog(monkeypatch):
    """الرياض → city 1, جدة → city 2; «القصيم» is a region and does not resolve. Only «حي قرطبة» is
    attested, and only for city 1."""
    monkeypatch.setattr(A, "to_catalog", lambda city_ar, hint=None: {"الرياض": (1, 100), "جدة": (2, 200)}.get(city_ar, (None, None)))
    monkeypatch.setattr(A, "find_district_in_text",
                        lambda text, city_id: (text if (city_id == 1 and text == "حي قرطبة") else None))


