def page(title, ann, mon="", *, og="", intro="", badge="", furn="", h1="", img=""):
    return ("<html><head>" + title + og + "</head><body>" + badge + h1 + intro + furn
            + '<div class="tabs-contents">' + ann + "</div>" + mon + "</div>" + img + "</body></html>")


REEM_PAGE = page(REEM_TITLE, REEM_ANN, REEM_MON, og=REEM_OG, intro=REEM_INTRO, furn=REEM_FURN, h1=REEM_H1, img=WADI_IMG)


# ── 1. grain ─────────────────────────────────────────────────────────────────────────────────────
def test_every_unit_type_is_its_own_row():
    rows, why, skips = A.map_units(REEM, REEM_PAGE)
    assert why == "" and skips == {}
    assert [r["ad_number"] for r in rows] == [
        "AZRal-reem-studio-apartment", "AZRal-reem-1-bedroom-apartment", "AZRal-reem-2-bedroom-apartment",
        "AZRal-reem-3-bedroom-apartment", "AZRal-reem-3-bedroom-townhouse", "AZRal-reem-4-bedroom-villa"]
    assert [r["property_type"] for r in rows] == ["Studio", "Apartment", "Apartment", "Apartment", "Villa", "Villa"]
    assert [r["bedrooms"] for r in rows] == [None, 1, 2, 3, 3, 4]
    assert {r["listing_url"] for r in rows} == {REEM} and rows[0]["title"] == "Al Reem – Studio Apartment"
    assert rows[0]["source"] == "Azure" and rows[0]["transaction_type"] == "Rent"


def test_a_repeated_unit_name_gets_a_stable_ordinal_suffix():
    doubled = REEM_ANN.replace("1 Bedroom Apartment", "Studio Apartment", 1)
    rows = A.map_units(REEM, page(REEM_TITLE, doubled, og=REEM_OG))[0]
    assert rows[0]["ad_number"] == "AZRal-reem-studio-apartment" and rows[1]["ad_number"] == "AZRal-reem-studio-apartment-2"


# ── 2. price and period ──────────────────────────────────────────────────────────────────────────
def test_the_annual_tab_is_the_price_and_the_monthly_figure_is_only_text():
    rows = A.map_units(REEM, REEM_PAGE)[0]
    r = rows[1]
    assert r["price_annual"] == 99000 and r["rent_period"] == "annual"
    assert r["price_evidence"]["raw"] == "from 99 000 SAR" and r["price_evidence"]["kind"] == "annual"
    assert r["additional_info"]["price_note"] == "from"
    assert r["additional_info"]["monthly_installment_raw"] == "from 8 827 SAR/MONTH"
    assert r["price_annual"] != 8827 * 12, "the installment is never multiplied into the price"
    assert "price_total" not in r


def test_annual_price_parser_reads_the_sources_spacing_and_refuses_monthly_text():
    assert A.annual_price("from 125 000 SAR") == (125000, "from")
    assert A.annual_price("125 000 SAR") == (125000, None)
    assert A.annual_price("from 11 146 SAR/MONTH") == (None, None)
    assert A.annual_price("") == (None, None)


def test_a_monthly_panel_that_does_not_line_up_pairs_nothing():
    rows = A.map_units(REEM, page(REEM_TITLE, REEM_ANN, WADI_MON, og=REEM_OG))[0]
    assert all("monthly_installment_raw" not in r["additional_info"] for r in rows)


# ── 3/4. status and city ─────────────────────────────────────────────────────────────────────────
def test_fully_leased_and_coming_soon_pages_yield_no_rows():
    assert A.map_units(WADI, page(WADI_TITLE, WADI_ANN, WADI_MON, og=WADI_OG, badge=WADI_BADGE)) == ([], "fully_leased", {})
    assert A.map_units("https://azure.sa/compounds/palma-i", page(PALMA1_TITLE, "", badge=PALMA1_BADGE)) == ([], "coming_soon", {})
    assert A.map_units(WADI, page(WADI_TITLE, "", og=WADI_OG)) == ([], "no_units", {})


def test_the_city_is_read_from_the_pages_own_words_and_two_cities_is_ambiguous():
    assert A.page_city(REEM_PAGE) == ("الرياض", "")
    assert A.page_city(page(WADI_TITLE, WADI_ANN, og=WADI_OG)) == ("الرياض", ""), "wadi names Riyadh only in og:description"
    assert A.page_city(page(QASSIM_TITLE, QASSIM_ANN, intro=QASSIM_INTRO)) == (None, "city_ambiguous")
    assert A.map_units("https://azure.sa/compounds/qassim", page(QASSIM_TITLE, QASSIM_ANN, intro=QASSIM_INTRO)) == ([], "city_ambiguous", {})
    assert A.map_units(WADI, page("<title>Azure</title>", WADI_ANN)) == ([], "no_city", {})
    wadi_rows = A.map_units(WADI, page(WADI_TITLE, WADI_ANN, WADI_MON, og=WADI_OG))[0]
    assert wadi_rows[0]["price_annual"] == 125000 and wadi_rows[0]["additional_info"]["monthly_installment_raw"] == "from 11 146 SAR/MONTH"


# ── 5/6/7. type, furnished, district ─────────────────────────────────────────────────────────────
def test_bare_bedroom_names_are_refused_and_duplexes_map():
    rows, why, skips = A.map_units(KAFD, page(KAFD_TITLE, KAFD_ANN, KAFD_MON))
    assert why == "" and skips == {"type_unmapped": 4}
    assert [r["ad_number"] for r in rows] == ["AZRkafd-2-bedroom-duplex", "AZRkafd-3-bedroom-duplex", "AZRkafd-4-bedroom-duplex"]
    assert {r["property_type"] for r in rows} == {"Duplex"}
    assert A.unit_type_ar("4 Bedroom Triplex") is None and A.unit_type_ar("1 Bedroom") is None
    assert A.unit_type_ar("4 Bedroom Villas") == "فيلا" and A.unit_type_ar("3 Bedroom Townhouse") == "فيلا"
    assert A.unit_type_ar("4 Bedroom Penthouse") == "شقة"
    assert A.map_units("https://azure.sa/compounds/palma-ii", page(PALMA2_TITLE, PALMA2_ANN))[0][0]["property_type"] == "Villa"


def test_furnished_comes_from_the_blocks_own_words_and_options_are_not_amenities():
    rows = A.map_units(REEM, REEM_PAGE)[0]
    assert all(r["furnished"] is True for r in rows)
    bare = A.map_units(REEM, page(REEM_TITLE, REEM_ANN, og=REEM_OG))[0]
    assert all("furnished" not in r for r in bare), "no «Fully furnished» block → NULL"
    wadi = A.map_units(WADI, page(WADI_TITLE, WADI_ANN, og=WADI_OG))[0][0]
    assert wadi["additional_info"]["unit_options"] == "Optional: Terrace, Backyard"
    assert "balcony_terrace" not in wadi and "garden" not in wadi


