# ── 8. removal oracle ────────────────────────────────────────────────────────────────────────────
def test_the_unit_signal_and_the_shared_law(monkeypatch):
    sig = A._unit_signal(("studio-apartment",))
    assert sig(404, "", False) == "gone"
    assert sig(200, REEM_PAGE, False) == "live"
    assert sig(200, page(WADI_TITLE, WADI_ANN, badge=WADI_BADGE), False) == "gone", "Fully Leased is the status the crawl skips"
    assert sig(200, page(WADI_TITLE, WADI_ANN), False) == "gone", "served, but this unit type is not listed"
    assert sig(200, "<html>The page is not found</html>", False) is None
    assert sig(403, REEM_PAGE, False) is None
    served = {"status": 403, "body": REEM_PAGE}
    monkeypatch.setattr(http_liveness.LivenessProbe, "fetch", lambda self, url: (served["status"], served["body"], False))
    monkeypatch.setattr(http_liveness, "time", types.SimpleNamespace(sleep=lambda *_: None))
    monkeypatch.setattr(A, "stored_listing_url", lambda tables: (lambda ad: REEM))
    verify = A._make_verify_gone(None)
    assert verify("AZRal-reem-studio-apartment")[0] == "unknown"
    served["status"] = 404
    verdict, why = verify("AZRal-reem-studio-apartment")
    assert verdict == "unknown" and "no row from this run" in why
    control = {"ad_number": "AZRal-reem-4-bedroom-villa", "listing_url": REEM, "additional_info": {"unit_type": "4 Bedroom Villa"}}
    served["status"], served["body"] = 200, page(REEM_TITLE, REEM_ANN.replace("Studio Apartment", "Penthouse Suite"))
    assert A._make_verify_gone(control)("AZRal-reem-studio-apartment")[0] == "gone"
    assert verify("AZR")[0] == "unknown"


def test_key_of_survives_a_hyphenated_compound_slug(monkeypatch):
    """Regression (review 2026-09-24): al-reem/palma-i/palma-ii all have a hyphen in the SLUG as
    well as in the unit key, so a generic string split cannot tell them apart. Reproduced live
    against the real, unmodified al-reem page the same day: the OLD regex-split key_of() extracted
    'reem-studio-apartment' (wrong) instead of 'studio-apartment', so verify_gone() reported a
    still-live unit as 'gone' — exactly the false-kill class verify_gone exists to prevent. Assert
    the fixed key_of() (via the row's own stored listing_url) reads the SAME unchanged, still-live
    REEM_PAGE as 'live' for every one of its hyphenated-key units."""
    monkeypatch.setattr(http_liveness.LivenessProbe, "fetch", lambda self, url: (200, REEM_PAGE, False))
    monkeypatch.setattr(http_liveness, "time", types.SimpleNamespace(sleep=lambda *_: None))
    monkeypatch.setattr(A, "stored_listing_url", lambda tables: (lambda ad: REEM))
    verify = A._make_verify_gone(None)
    for ad in ("AZRal-reem-studio-apartment", "AZRal-reem-3-bedroom-townhouse", "AZRal-reem-4-bedroom-villa"):
        assert verify(ad) == ("live", "source still serves this listing (HTTP 200)"), ad
    # a repeated-name ordinal suffix (map_units' "-2") must still resolve to the base key
    assert verify("AZRal-reem-studio-apartment-2") == ("live", "source still serves this listing (HTTP 200)")


def test_a_unique_unit_named_with_a_trailing_number_is_never_falsely_reported_gone(monkeypatch):
    """Regression (review 2026-09-24, second false-kill in the SAME fix): key_of() must not guess
    a write-time dedup ordinal ("-2" on a REPEATED name) is present just because the ad_number's
    remainder ends in "-<digits>". A UNIQUE unit whose own name ends in a bare number — a plausible
    compound naming like "Villa 5" — produces the identical shape. Reproduced with the real,
    unmodified map_units()/key_of()/_unit_signal() on a page whose only change is renaming one real
    REEM unit ("Studio Apartment" -> "Villa 5", a name that appears ONCE, so map_units' own
    dedup counter never fires): the OLD code stripped the real trailing "5", recovered "villa"
    instead of "villa-5", found no match in the live key list, and reported a still-live unit
    gone. The fixed key_of() tries the literal "villa-5" first."""
    villa5_page = REEM_PAGE.replace("Studio Apartment", "Villa 5")
    rows, _why, _skips = A.map_units(REEM, villa5_page)
    ad_numbers = [r["ad_number"] for r in rows]
    assert "AZRal-reem-villa-5" in ad_numbers, "map_units itself must key this unit as villa-5"

    monkeypatch.setattr(http_liveness.LivenessProbe, "fetch", lambda self, url: (200, villa5_page, False))
    monkeypatch.setattr(http_liveness, "time", types.SimpleNamespace(sleep=lambda *_: None))
    monkeypatch.setattr(A, "stored_listing_url", lambda tables: (lambda ad: REEM))
    verify = A._make_verify_gone(None)
    assert verify("AZRal-reem-villa-5") == ("live", "source still serves this listing (HTTP 200)")
    # the genuine-dedup path (a REPEATED name -> "-2" ordinal) must still resolve correctly too,
    # on this SAME page, so the fix does not trade one false-kill for the other. A "gone" verdict
    # needs a positive control (fail-closed design), like test_the_unit_signal_and_the_shared_law.
    control = {"ad_number": "AZRal-reem-villa-5", "listing_url": REEM,
               "additional_info": {"unit_type": "Villa 5"}}
    assert A._make_verify_gone(control)("AZRal-reem-studio-apartment") == \
        ("gone", "source confirms removal (HTTP 200)"), \
        "renamed away in this fixture, so this ad_number should now read gone, not live"


# ── 9. main() ────────────────────────────────────────────────────────────────────────────────────
class _FakeResp:
    def __init__(self, status, text):
        self.status_code, self.text = status, text


def _wire(monkeypatch, pages: dict, argv: list[str]):
    sitemap = "<urlset>" + "".join(f"<loc>{u}</loc>" for u in pages) + "<loc>https://azure.sa/compounds/wadi/units</loc><loc>https://azure.sa/compounds</loc></urlset>"

    class _S:
        def get(self, url, timeout=0):
            if url.endswith("/sitemap.xml"):
                return _FakeResp(200, sitemap)
            got = pages[url]
            if isinstance(got, Exception):
                raise got
            return _FakeResp(*got)

    calls: dict = {"end_run": [], "batch": [], "prune": [], "retire": []}
    monkeypatch.setattr(A, "session", lambda: _S())
    monkeypatch.setattr(A, "time", types.SimpleNamespace(sleep=lambda *_: None))
    monkeypatch.setattr(A.db, "begin_run", lambda p: 7)
    monkeypatch.setattr(A.db, "end_run", lambda run_id, **kw: (calls["end_run"].append(kw), True)[1])
    monkeypatch.setattr(A.db, "_wasalt_batch", lambda table, rows: calls["batch"].append((table, len(rows))))
    monkeypatch.setattr(A.db, "retire_superseded_siblings", lambda **kw: calls["retire"].append(kw) or 0)
    monkeypatch.setattr(A.db, "prune_unseen", lambda table, seen, **kw: calls["prune"].append((table, set(seen))) or 0)
    monkeypatch.setattr(A.db, "mark_direct_alive", lambda row, *, oracle: row)
    monkeypatch.setattr("sys.argv", ["run.py", *argv])
    return calls


def test_main_writes_the_tally_into_end_run_notes_and_prunes_after_a_complete_walk(monkeypatch):
    pages = {REEM: (200, REEM_PAGE), WADI: (200, page(WADI_TITLE, WADI_ANN, badge=WADI_BADGE)),
             KAFD: (200, page(KAFD_TITLE, KAFD_ANN)), "https://azure.sa/compounds/gone": (404, "not found")}
    calls = _wire(monkeypatch, pages, [])
    assert A.main() == 0
    kw = calls["end_run"][0]
    assert kw["ok"] is True and kw["rows_seen"] == 4 and kw["rows_upserted"] == 9
    assert "fully_leasedx1" in kw["notes"] and "type_unmappedx4" in kw["notes"] and "http_404x1" in kw["notes"]
    assert kw["check_tables"] == ["azure_residential_listings", "azure_commercial_listings"]
    assert calls["batch"] == [("azure_residential_listings", 9)]
    assert calls["retire"][0]["source"] == "Azure" and len(calls["retire"][0]["res_ads"]) == 9
    assert calls["prune"][0][0] == "azure_residential_listings" and len(calls["prune"][0][1]) == 9


def test_main_never_prunes_after_an_incomplete_walk_and_dry_run_writes_nothing(monkeypatch):
    calls = _wire(monkeypatch, {REEM: (200, REEM_PAGE), WADI: RuntimeError("timeout")}, [])
    assert A.main() == 0 and calls["prune"] == [] and "unreachablex1" in calls["end_run"][0]["notes"]
    calls = _wire(monkeypatch, {REEM: (200, REEM_PAGE)}, ["--dry-run"])
    assert A.main() == 0 and calls["batch"] == [] and calls["end_run"] == []


